public readonly record struct Money(long Cents, string Currency)
{
    private static void Same(Money l, Money r)
    {
        if (l.Currency != r.Currency)
            throw new InvalidOperationException($"cannot combine {l.Currency} with {r.Currency}");
    }

    public static Money operator +(Money l, Money r) { Same(l, r); return l with { Cents = l.Cents + r.Cents }; }
    public static Money operator -(Money l, Money r) { Same(l, r); return l with { Cents = l.Cents - r.Cents }; }
    public static Money operator *(Money m, int n) => m with { Cents = m.Cents * n };
    public static Money operator *(int n, Money m) => m * n;

    public static bool operator <(Money l, Money r) { Same(l, r); return l.Cents < r.Cents; }
    public static bool operator >(Money l, Money r) { Same(l, r); return l.Cents > r.Cents; }
    public static bool operator <=(Money l, Money r) { Same(l, r); return l.Cents <= r.Cents; }
    public static bool operator >=(Money l, Money r) { Same(l, r); return l.Cents >= r.Cents; }

    public override string ToString()
    {
        long abs = Math.Abs(Cents);
        return $"{(Cents < 0 ? "-" : "")}{abs / 100}.{abs % 100:00} {Currency}";
    }
}

unitTests:
Test("arithmetic", () =>
{
    var a = new Money(1250, "EUR");
    CheckEq((a + new Money(75, "EUR")).ToString(), "13.25 EUR");
    CheckEq((a - new Money(1555, "EUR")).ToString(), "-3.05 EUR");
    CheckEq((3 * a).ToString(), "37.50 EUR");
    CheckEq((a * 2).Cents, 2500L);
    CheckEq(new Money(5, "USD").ToString(), "0.05 USD");
});

Test("comparisons", () =>
{
    var small = new Money(100, "USD");
    var big = new Money(250, "USD");
    Check(small < big && big > small && small <= small && big >= small, "the comparisons should follow the cents");
    Check(small == new Money(100, "USD"), "records compare by value");
});

Test("currencies must match", () =>
{
    var eur = new Money(100, "EUR");
    var usd = new Money(100, "USD");
    CheckThrows<InvalidOperationException>(() => { var _ = eur + usd; });
    CheckThrows<InvalidOperationException>(() => { var _ = eur < usd; });
});

